const prev = $('Merge Creative Id').first().json;
const created = $input.first().json;
const adId = created.id || created.ad_id;
if (!adId) throw new Error('Create Ad PAUSED returned no id');
const mc = Object.assign({}, prev.metaCreate || {}, { adId: String(adId) });
const plan = (prev.bundle && prev.bundle.ledgerPlan) || {};
const claim = prev.ledgerClaim || {};
return [{ json: Object.assign({}, prev, {
  metaCreate: mc,
  ledgerUpsert: {
    operationKey: plan.operationKey,
    appId: plan.appId,
    experimentRunId: plan.experimentRunId || '',
    provider: plan.provider || 'meta',
    environment: plan.environment || 'sandbox',
    creativeRevision: plan.creativeRevision || 'image-v1',
    contentFingerprint: plan.contentFingerprint || '',
    creativeSha256: plan.creativeSha256 || '',
    phase: 'verified',
    campaignId: mc.campaignId || '',
    adSetId: mc.adSetId || '',
    imageHash: mc.imageHash || '',
    creativeId: mc.creativeId || '',
    adId: mc.adId || '',
    lockOwner: claim.lockOwner || '',
    lockExpiresAt: claim.lockExpiresAt || '',
    resumeFrom: '',
    outcome: 'in_progress',
    lastError: '',
  }
}) }];

