const prev = $('Prepare Ledger Verified').first().json;
const plan = (prev.bundle && prev.bundle.ledgerPlan) || {};
const mc = prev.metaCreate || {};
const preview = (prev.bundle && prev.bundle.writeBackAfterCreatePausedOnly && prev.bundle.writeBackAfterCreatePausedOnly.ads && prev.bundle.writeBackAfterCreatePausedOnly.ads.meta) || {};
const writeBackMeta = {
  status: 'created_paused',
  campaignId: mc.campaignId,
  adSetId: mc.adSetId,
  creativeId: mc.creativeId,
  adId: mc.adId,
  landingUrl: preview.landingUrl || (prev.bundle && prev.bundle.computed && prev.bundle.computed.destinationUrl) || null,
  dailyBudget: preview.dailyBudget != null ? preview.dailyBudget : (prev.bundle && prev.bundle.computed && prev.bundle.computed.dailyBudget),
  createdAt: new Date().toISOString(),
  lastSyncedAt: null,
  creativeRevision: plan.creativeRevision || 'image-v1',
};
const required = ['campaignId','adSetId','creativeId','adId'];
const missing = required.filter(function (k) { return !writeBackMeta[k]; });
if (missing.length) throw new Error('WRITEBACK_INCOMPLETE_IDS: ' + missing.join(','));
return [{ json: Object.assign({}, prev, {
  sandboxDriveAppJsonFileId: '1V1UQP4vH3O8xYexn-Jphfn29Sv30Z6xn',
  writeBackMeta: writeBackMeta,
  writeBackProofOnly: true,
}) }];

const prev = $('Prepare Write-Back').first().json;
const item = $input.first();
let appJson = null;
if (item.json && item.json.ads) appJson = item.json;
else if (item.binary && item.binary.data) {
  const bin = item.binary.data;
  const raw = bin.data;
  if (typeof raw === 'string') {
    const text = Buffer.from(raw, bin.encoding === 'base64' || !bin.encoding ? 'base64' : bin.encoding).toString('utf8');
    appJson = JSON.parse(text);
  }
}
if (!appJson || typeof appJson !== 'object') throw new Error('WRITEBACK_APPJSON_REQUIRED: Drive download did not yield app.json');
const rootBefore = appJson.status;
const metaIn = prev.writeBackMeta || {};
const clone = JSON.parse(JSON.stringify(appJson));
if (!clone.ads) clone.ads = {};
if (!clone.ads.meta) clone.ads.meta = {};
['status','campaignId','adSetId','creativeId','adId','landingUrl','dailyBudget','createdAt','lastSyncedAt','creativeRevision'].forEach(function (k) {
  if (Object.prototype.hasOwnProperty.call(metaIn, k) && metaIn[k] != null) clone.ads.meta[k] = metaIn[k];
});
clone.status = rootBefore;
const outBin = Buffer.from(JSON.stringify(clone, null, 2), 'utf8').toString('base64');
const plan = (prev.bundle && prev.bundle.ledgerPlan) || {};
const mc = prev.metaCreate || {};
return [{
  json: Object.assign({}, prev, {
    mergedAppJson: clone,
    rootStatusUnchanged: clone.status === rootBefore,
    fileId: prev.sandboxDriveAppJsonFileId,
    ledgerUpsert: {
      operationKey: plan.operationKey,
      appId: plan.appId,
      experimentRunId: plan.experimentRunId || '',
      provider: plan.provider || 'meta',
      environment: plan.environment || 'sandbox',
      creativeRevision: plan.creativeRevision || 'image-v1',
      contentFingerprint: plan.contentFingerprint || '',
      creativeSha256: plan.creativeSha256 || '',
      phase: 'writeback_done',
      campaignId: mc.campaignId || '',
      adSetId: mc.adSetId || '',
      imageHash: mc.imageHash || '',
      creativeId: mc.creativeId || '',
      adId: mc.adId || '',
      lockOwner: '',
      lockExpiresAt: '',
      resumeFrom: '',
      outcome: 'already_complete',
      lastError: '',
    },
  }),
  binary: { data: { data: outBin, mimeType: 'application/json', fileName: 'app.json', encoding: 'base64' } },
}];

const prev = $('Merge ads.meta Write-Back').first().json;
if (!prev.ledgerUpsert) throw new Error('WRITEBACK_LEDGER_UPSERT_MISSING');
return [{ json: prev }];
